"samurott": {"role": "Physical setup attacker with priority", "item": "Life Orb", "ability": "Torrent", "nature": "Adamant", "moves": ["Swords Dance", "Liquidation", "Aqua Jet", "Megahorn"], "plan": "Use a safe Swords Dance turn, then attack with Liquidation or finish a weakened target with Aqua Jet. Megahorn offers Bug coverage against a suitable target.", "caution": "Life Orb costs HP and Megahorn can miss. Electric and Grass attacks are super effective. This standard Water form does not have Hisuian Samurott’s Dark typing or Sharpness.", "partners": "A Ground teammate covers Electric attacks. A Steel partner can resist Grass and offer a sturdier switch-in.", "alternative": "feraligatr", "alternativeReason": "Feraligatr provides Dragon Dance and Sheer Force instead of Swords Dance and Water priority."},
