"rillaboom": {"role": "Physical attacker and terrain support", "item": "Choice Band", "ability": "Grassy Surge", "nature": "Adamant", "moves": ["Wood Hammer", "Grassy Glide", "Knock Off", "U-turn"], "plan": "Grassy Surge starts Grassy Terrain on entry. Grassy Glide gains priority while Grassy Terrain is active; U-turn can bring in a teammate when a matchup is unfavorable.", "caution": "Choice Band locks you into one move until switching, and Wood Hammer causes recoil. Terrain also helps eligible opponents recover and weakens Earthquake against grounded targets. Priority depends on terrain remaining active.", "partners": "A Fire or Steel teammate covers several Grass weaknesses. Consider how Grassy Terrain affects your own Ground attacks.", "alternative": "meowscarada", "alternativeReason": "Meowscarada offers greater Speed and Dark typing without starting Grassy Terrain."},
