"hydreigon": {"role": "Special setup attacker", "item": "Leftovers", "ability": "Levitate", "nature": "Timid", "moves": ["Dark Pulse", "Dragon Pulse", "Flamethrower", "Nasty Plot"], "plan": "Levitate normally provides Ground immunity. Find a safe Nasty Plot turn before attacking; Flamethrower offers coverage against Steel targets that resist Dragon Pulse.", "caution": "Fairy attacks deal 4× damage and Fairy types ignore Dragon Pulse. Ice, Fighting, Bug and Dragon attacks also threaten it. Effects such as Mold Breaker can bypass Levitate.", "partners": "A Steel teammate can resist Fairy, Ice, Bug and Dragon attacks. Add physical damage to avoid relying only on special attackers.", "alternative": "dragapult", "alternativeReason": "Dragapult offers more Speed and Ghost typing, with a different attacking toolkit."},
"garganacl": {"role": "Defensive pressure and recovery", "item": "Leftovers", "ability": "Sturdy", "nature": "Impish", "moves": ["Salt Cure", "Recover", "Body Press", "Protect"], "plan": "Use Salt Cure against an eligible target to apply ongoing damage, then Recover or Protect when the matchup permits. Body Press uses Defense rather than Attack.", "caution": "Sturdy requires full HP and can be broken by hazards or chip damage. This set uses Sturdy, not Purifying Salt, so it has no ability-based status immunity or Ghost damage reduction. Water, Grass, Fighting, Ground and Steel attacks are super effective.", "partners": "A Flying teammate covers Ground and can resist Fighting. A Grass partner resists Water and Grass; check Steel attacks too.", "alternative": "tyranitar", "alternativeReason": "Tyranitar offers a more attacking Rock role and sand support, with Dark typing and different weaknesses."},
"electivire": {"role": "Physical attacker with Electric immunity", "item": "Life Orb", "ability": "Motor Drive", "nature": "Jolly", "moves": ["Thunder Punch", "Ice Punch", "Earthquake", "Knock Off"], "plan": "A predicted Electric attack can activate Motor Drive, granting immunity to that attack and raising Speed. Attack with Thunder Punch or use coverage against a suitable target.", "caution": "Motor Drive is not an unconditional Speed boost and can be bypassed by some ability-ignoring effects. Life Orb costs HP. Ground attacks are super effective; Flying types avoid Earthquake.", "partners": "A Flying teammate covers Ground attacks. A special attacker helps avoid relying entirely on physical damage.", "alternative": "jolteon", "alternativeReason": "Jolteon offers greater natural Speed and special attacks with Volt Absorb instead of Motor Drive."},
